+const { pct } = require('./money');
+const { tax } = require('./tax');
+
+function computeTotal({ subtotal, couponPercent = 0, taxPercent = 0, shipping = 0 }) {
+  const discount = pct(subtotal, couponPercent);
+  const taxed = tax(subtotal, taxPercent);
+  return subtotal - discount + taxed + shipping;
+}
+
+module.exports = { computeTotal };
